package za.co.gpbrij.cph.domain;
import jakarta.persistence.*; import java.time.Instant;
@Entity public class Approval { @Id @GeneratedValue(strategy=GenerationType.UUID) private String id; @ManyToOne(optional=false) private Payment payment; private String approver; private String decision; private String comments; private Instant decidedAt=Instant.now(); public String getId(){return id;} public Payment getPayment(){return payment;} public void setPayment(Payment v){payment=v;} public String getApprover(){return approver;} public void setApprover(String v){approver=v;} public String getDecision(){return decision;} public void setDecision(String v){decision=v;} public String getComments(){return comments;} public void setComments(String v){comments=v;} public Instant getDecidedAt(){return decidedAt;} }
